modernOrGood.snippet:
function tooltip(node, params) {
  function onEnter() { params.show = true; }
  // ✅ NEW: attach in the action, clean up in destroy()
  node.addEventListener('mouseenter', onEnter);
  return { update(p) {}, destroy() { node.removeEventListener('mouseenter', onEnter); } };
}
